  function showLocationToast(messageId, locName) {
    if (!locName || locName === '未知地点' || locName === '未知' || locName === 'none' || locName === '无') return;
    const toast = $(`#loc-toast-${messageId}`);
    if (toast.length) {
      toast.text(locName);
      toast.addClass('show');
      if (toast.data('timer')) clearTimeout(toast.data('timer'));
      const timer = setTimeout(() => {
        toast.removeClass('show');
      }, 3000);
      toast.data('timer', timer);
    }
  }

  async function performBack(messageId) {
    const state = gameStates[messageId];
    if (!state || state.showingChoices) return;

    let startIdx = state.currentIndex - 1;

    if (state.isTypewriting) {
        cancelAnimationFrame(state.typeTimer);
        state.isTypewriting = false;
        state.skipTypewriter = false;
        state.typeTimer = null;
        state.typeFunction = null;
        state.processing = false;

        startIdx = state.currentIndex;
    }

    if (state.processing) return;

    let targetIndex = -1;
    let dialogueCount = 0;

    for (let i = startIdx; i >= 0; i--) {
        if (state.data.scenes[i].type === 'dialogue') {
            dialogueCount++;
            if (dialogueCount === 2) {
                targetIndex = i;
                break;
            }
        }
    }

    if (targetIndex === -1) targetIndex = 0;

    state.processing = true;

    hideAllCharacters(messageId);
    hideCG(messageId);
    $(`#bg-${messageId}`).css({'background-image': 'none', 'background-color': '#000'});
    let lastBgm = 'none';

    for (let i = 0; i < targetIndex; i++) {
        const scene = state.data.scenes[i];
        if (scene.type === 'command') {
            switch (scene.command) {
                case 'bg': setBackground(messageId, scene.args[0], scene.args[1], 0); break;
                case 'show': case 'alter': showCharacter(messageId, scene.args[0], scene.args[1]?.toUpperCase(), scene.args[2]); break;
                case 'hide': case 'leave': hideCharacter(messageId, scene.args[0]); break;
                case 'hide_all': hideAllCharacters(messageId); break;
                case 'cg': showCG(messageId, scene.args[0]); break;
                case 'hide_cg': hideCG(messageId); break;
                case 'bgm': lastBgm = scene.args[0]; break;
            }
        } else if (scene.type === 'dialogue') {
            if (scene.character !== '旁白') {
                if (scene.position && scene.sprite && !['无', 'None', 'null', 'none', '-'].includes(scene.sprite)) {
                    showCharacter(messageId, scene.character, scene.position, scene.sprite);
                }
            }
        }
    }

    playBGM(messageId, lastBgm);

    state.currentIndex = targetIndex;
    state.processing = false;
    processNextScene(messageId);
  }

  function setupGameEvents(messageId, gameData) {
    const wrapper = $(`.galgame-wrapper-${messageId}`);
    const container = wrapper.find(`.galgame-container-${messageId}`);
    if (!container.length) return;

    $(`.galgame-char-${messageId}`).on('error', function() {
      $(this).attr('src', EMPTY_IMAGE).removeClass('active');
    });
    $(`.galgame-cg-${messageId} img`).on('error', function() {
      $(this).attr('src', EMPTY_IMAGE);
      $(this).parent().removeClass('active');
    });

    container.find(`.gsm-hidden-checkbox-${messageId}, .gsm-overlay-mask-${messageId}, .gsm-status-panel-${messageId}`).on('click dblclick', function(e) {
      e.stopPropagation();
    });

    $(`#back-btn-${messageId}`).on('click', function(e) {
        e.stopPropagation();
        performBack(messageId);
    });

    $(`#next-btn-${messageId}`).on('click', function(e) {
        e.stopPropagation();
        const state = gameStates[messageId];
        if (!state || state.showingChoices) return;

        if (state.isTypewriting) {
            state.skipTypewriter = true;
            if (typeof state.typeFunction === 'function') {
                state.typeFunction();
            }
            return;
        }

        if (state.processing) return;

        if (state.autoTimer) {
            clearTimeout(state.autoTimer);
            state.autoTimer = null;
        }
        processNextScene(messageId);
    });

    container.on('click', function (e) {
      const state = gameStates[messageId];
      if (!state) return;

      if (state.pendingBgm) {
          const audio = window.__GAL_BGM_AUDIO__;
          if (audio && audio.paused) {
              audio.play().then(() => {
                  state.pendingBgm = null;
              }).catch(()=>{});
          }
      }

      if (state.isHidden) {
          $(`#dialogue-box-${messageId}`).css('opacity', '1');
          $(`#controls-wrapper-${messageId}`).css('opacity', '1');
          state.isHidden = false;
          return;
      }

      if ($(e.target).closest('.galgame-history-modal-' + messageId).length ||
          $(e.target).closest('.galgame-cg-modal-' + messageId).length ||
          $(e.target).closest('.galgame-cg-viewer-' + messageId).length ||
          $(e.target).closest('.galgame-choices-' + messageId).length ||
          $(e.target).closest(`.gsm-status-panel-${messageId}`).length ||
          $(e.target).closest(`.gsm-overlay-mask-${messageId}`).length ||
          $(e.target).closest(`.gsm-hidden-checkbox-${messageId}`).length ||
          $(e.target).closest(`.galgame-bgm-panel-${messageId}`).length ||
          $(e.target).closest(`.galgame-display-panel-${messageId}`).length ||
          $(e.target).closest(`.galgame-controls-wrapper-${messageId}`).length) return;

      e.stopPropagation();
      if (state.showingChoices) return;

      if (state.isTypewriting) {
        state.skipTypewriter = true;
        if (typeof state.typeFunction === 'function') {
            state.typeFunction();
        }
        return;
      }

      if (state.processing) return;

      if (state.autoTimer) {
        clearTimeout(state.autoTimer);
        state.autoTimer = null;
      }
      processNextScene(messageId);
    });

    container.on('dblclick', function (e) {
      if ($(e.target).closest('.galgame-history-modal-' + messageId).length ||
          $(e.target).closest('.galgame-cg-modal-' + messageId).length ||
          $(e.target).closest('.galgame-cg-viewer-' + messageId).length ||
          $(e.target).closest('.galgame-choices-' + messageId).length ||
          $(e.target).closest(`.gsm-status-panel-${messageId}`).length ||
          $(e.target).closest(`.gsm-overlay-mask-${messageId}`).length ||
          $(e.target).closest(`.gsm-hidden-checkbox-${messageId}`).length ||
          $(e.target).closest(`.galgame-bgm-panel-${messageId}`).length ||
          $(e.target).closest(`.galgame-display-panel-${messageId}`).length ||
          $(e.target).closest(`.galgame-controls-wrapper-${messageId}`).length ||
          $(e.target).closest(`.galgame-dialogue-${messageId}`).length) return;

      e.stopPropagation();
      const el = wrapper[0];
      if (!document.fullscreenElement && !document.webkitFullscreenElement) {
        if (el.requestFullscreen) el.requestFullscreen().catch(()=>{});
        else if (el.webkitRequestFullscreen) el.webkitRequestFullscreen();
      } else {
        if (document.exitFullscreen) document.exitFullscreen().catch(()=>{});
        else if (document.webkitExitFullscreen) document.webkitExitFullscreen();
      }
