    $(`#hide-btn-${messageId}`).on('click', function(e) {
        e.stopPropagation();
        $(`#dialogue-box-${messageId}`).css('opacity', '0');
        $(`#controls-wrapper-${messageId}`).css('opacity', '0');
        if(gameStates[messageId]) gameStates[messageId].isHidden = true;
